def count_divisors(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def is_exotic(n):
    tau_n = count_divisors(n)
    # n is exotic if tau(n) = 2 * m where m is odd.
    # This means tau(n) must be even, and tau(n)/2 must be odd.
    if tau_n % 2 != 0:
        return False
    m = tau_n // 2
    return m % 2 != 0

def find_kth_exotic(k):
    count = 0
    n = 1
    exotic_numbers = []
    while count < k:
        if is_exotic(n):
            count += 1
            exotic_numbers.append(n)
        n += 1
    return exotic_numbers[k-1]

# Find the 132nd exotic integer
target_k = 132
result = find_kth_exotic(target_k)
print(f"The {target_k}th exotic integer is: {result}")

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_nth_prime(n):
    count = 0
    num = 1
    while count < n:
        num += 1
        if is_prime(num):
            count += 1
    return num

